const lines = stdin.replace(/\r/g, '').split('\n');
const [method, target] = lines[0].trim().split(/\s+/);

const headers = {};
for (let i = 1; i < lines.length; i++) {
  const line = lines[i];
  if (line.trim() === '') break;
  const idx = line.indexOf(':');
  if (idx === -1) continue;
  headers[line.slice(0, idx).trim().toLowerCase()] = line.slice(idx + 1).trim();
}

const q = target.indexOf('?');
const path = q === -1 ? target : target.slice(0, q);
const query = q === -1 ? '' : target.slice(q + 1);
const decode = (s) => decodeURIComponent(s.replace(/\+/g, ' '));
const pairs = query.split('&').filter(Boolean).map((part) => {
  const eq = part.indexOf('=');
  const key = eq === -1 ? part : part.slice(0, eq);
  const value = eq === -1 ? '' : part.slice(eq + 1);
  return decode(key) + '=' + decode(value);
});

const safe = ['GET', 'HEAD', 'OPTIONS'].includes(method);
const idempotent = safe || ['PUT', 'DELETE'].includes(method);

console.log('Method: ' + method);
console.log('Path: ' + path);
console.log('Query: ' + (pairs.length ? pairs.join('; ') : 'none'));
console.log('Host: ' + (headers.host || 'missing'));
console.log('Safe: ' + (safe ? 'yes' : 'no'));
console.log('Idempotent: ' + (idempotent ? 'yes' : 'no'));
